solution:
use xiom.io;

enum CalcResult {
  Value(n: Int),
  Error(msg: Str),
}

fn safe_divide(a: Int, b: Int) -> CalcResult {
  if b == 0 {
    return CalcResult.Error("Division by zero");
  }
  return CalcResult.Value(a / b);
}

fn extract_value(r: CalcResult) -> Int {
  match r {
    Value(n) => { return n; }
    Error(_) => { return -1; }
  }
}

fn main() -> Int {
  let r1 = safe_divide(100, 0);
  let r2 = safe_divide(100, 4);
  return extract_value(r1) + extract_value(r2);
}
